from pathlib import Path
from collections import Counter
for p in sorted(Path('/workspace/data').glob('*.fasta'), key=lambda p:int(p.stem)):
    lines=p.read_text().splitlines()
    headers=[s[1:] for s in lines if s.startswith('>')]
    lengths=[]
    for s in lines:
        if s.startswith('>'): lengths.append(0)
        elif s.strip(): lengths[-1]+=len(s.strip())
    print(p.name, len(headers), Counter(lengths).most_common(4), [h[:180] for h in headers[:3]])
